package ro.leo.visual;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.CalendarContract;import java.io.IOException;import java.util.*;import org.json.*;
/** Only Calendar Leo. Provider replacement is one transaction; never touches account calendars. */
final class CalendarArchive {
 static long calendar(Context c){try(Cursor x=c.getContentResolver().query(CalendarContract.Calendars.CONTENT_URI,new String[]{"_id"},"account_name=? AND account_type=? AND name=?",new String[]{"Leo local","LOCAL","Leo"},null)){return x!=null&&x.moveToFirst()?x.getLong(0):-1;}}
 static JSONArray snapshot(Context c)throws Exception{JSONArray out=new JSONArray();long id=calendar(c);if(id<0)return out;try(Cursor x=c.getContentResolver().query(CalendarContract.Events.CONTENT_URI,new String[]{"_id","title","dtstart","dtend","duration","rrule","eventTimezone","allDay"},"calendar_id=? AND deleted=0",new String[]{""+id},"dtstart ASC")){while(x!=null&&x.moveToNext()){if(out.length()>=500)throw new IOException("Calendar peste 500 de evenimente");JSONObject e=new JSONObject().put("title",x.getString(1)==null?"Eveniment":x.getString(1)).put("start",x.getLong(2)).put("end",x.isNull(3)?JSONObject.NULL:x.getLong(3)).put("duration",x.isNull(4)?JSONObject.NULL:x.getString(4)).put("rule",x.isNull(5)?JSONObject.NULL:x.getString(5)).put("zone",x.getString(6)==null?TimeZone.getDefault().getID():x.getString(6)).put("allDay",x.getInt(7));JSONArray alerts=new JSONArray();try(Cursor r=c.getContentResolver().query(CalendarContract.Reminders.CONTENT_URI,new String[]{"minutes"},"event_id=? AND method=?",new String[]{""+x.getLong(0),"1"},null)){while(r!=null&&r.moveToNext()){if(alerts.length()>=5)throw new IOException("Prea multe notificări");alerts.put(r.getInt(0));}}e.put("alerts",alerts);out.put(e);}}validate(out);return out;}
 static void validate(JSONArray rows)throws Exception{if(rows.length()>500)throw new IOException("Maximum 500 de evenimente");Set<String> zones=new HashSet<String>(Arrays.asList(TimeZone.getAvailableIDs()));for(int n=0;n<rows.length();n++){JSONObject e=rows.getJSONObject(n);long start=e.getLong("start");if(e.getString("title").length()>2048||start<0||start>4165516800000L||!zones.contains(e.getString("zone"))||(e.getInt("allDay")!=0&&e.getInt("allDay")!=1))throw new IOException("Eveniment invalid");if(e.isNull("rule")){if(e.isNull("end")||e.getLong("end")<=start||e.getLong("end")-start>366L*86400000)throw new IOException("Durată invalidă");}else{if(!Arrays.asList("FREQ=DAILY","FREQ=WEEKLY","FREQ=MONTHLY").contains(e.getString("rule"))||!e.getString("duration").matches("PT[1-9][0-9]{0,7}S"))throw new IOException("Repetare nesuportată");}JSONArray a=e.getJSONArray("alerts");if(a.length()>5)throw new IOException("Prea multe notificări");for(int i=0;i<a.length();i++)if(a.getInt(i)<0||a.getInt(i)>525600)throw new IOException("Notificare invalidă");}}
 static void apply(Context c,JSONArray rows)throws Exception{replace(c,rows,calendar(c));}
 static void replace(Context c,JSONArray rows,long id)throws Exception{validate(rows);ArrayList<ContentProviderOperation> ops=new ArrayList<ContentProviderOperation>();int calRef=-1;if(id<0){if(rows.length()==0)return;ContentValues v=new ContentValues();v.put("account_name","Leo local");v.put("account_type","LOCAL");v.put("name","Leo");v.put("calendar_displayName","Calendar Leo");v.put("calendar_color",0xff8b5fc9);v.put("calendar_access_level",700);v.put("ownerAccount","Leo local");v.put("visible",1);v.put("sync_events",1);v.put("calendar_timezone",TimeZone.getDefault().getID());Uri u=CalendarContract.Calendars.CONTENT_URI.buildUpon().appendQueryParameter("caller_is_syncadapter","true").appendQueryParameter("account_name","Leo local").appendQueryParameter("account_type","LOCAL").build();calRef=ops.size();ops.add(ContentProviderOperation.newInsert(u).withValues(v).build());}else ops.add(ContentProviderOperation.newDelete(CalendarContract.Events.CONTENT_URI).withSelection("calendar_id=?",new String[]{""+id}).build());for(int n=0;n<rows.length();n++){JSONObject e=rows.getJSONObject(n);ContentValues v=new ContentValues();if(id>=0)v.put("calendar_id",id);v.put("title",e.getString("title"));v.put("dtstart",e.getLong("start"));v.put("eventTimezone",e.getString("zone"));v.put("allDay",e.getInt("allDay"));if(e.isNull("rule"))v.put("dtend",e.getLong("end"));else{v.put("rrule",e.getString("rule"));v.put("duration",e.getString("duration"));}JSONArray alerts=e.getJSONArray("alerts");v.put("hasAlarm",alerts.length()>0?1:0);int ref=ops.size();ContentProviderOperation.Builder insert=ContentProviderOperation.newInsert(CalendarContract.Events.CONTENT_URI).withValues(v);if(calRef>=0)insert.withValueBackReference("calendar_id",calRef);ops.add(insert.build());for(int i=0;i<alerts.length();i++)ops.add(ContentProviderOperation.newInsert(CalendarContract.Reminders.CONTENT_URI).withValueBackReference("event_id",ref).withValue("method",1).withValue("minutes",alerts.getInt(i)).build());}if(!ops.isEmpty())c.getContentResolver().applyBatch(CalendarContract.AUTHORITY,ops);CalendarReminders.scheduleNow(c);}
}
